CREATE TABLE roles (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(100) UNIQUE NOT NULL, created_at TIMESTAMP NULL, updated_at TIMESTAMP NULL);
CREATE TABLE permissions (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(150) UNIQUE NOT NULL, created_at TIMESTAMP NULL, updated_at TIMESTAMP NULL);
CREATE TABLE role_permission (role_id BIGINT NOT NULL, permission_id BIGINT NOT NULL, PRIMARY KEY(role_id, permission_id));
CREATE TABLE users (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(150) NOT NULL, email VARCHAR(190) UNIQUE NOT NULL, password VARCHAR(255) NOT NULL, role_id BIGINT NULL, created_at TIMESTAMP NULL, updated_at TIMESTAMP NULL);
CREATE TABLE owners (id BIGINT PRIMARY KEY AUTO_INCREMENT, full_name VARCHAR(150) NOT NULL, phone VARCHAR(40) NOT NULL, email VARCHAR(190) NULL, address TEXT NULL, emergency_contact_name VARCHAR(150) NULL, emergency_contact_phone VARCHAR(40) NULL, created_by BIGINT NULL, created_at TIMESTAMP NULL, updated_at TIMESTAMP NULL, deleted_at TIMESTAMP NULL);
CREATE TABLE species (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(120) UNIQUE NOT NULL);
CREATE TABLE breeds (id BIGINT PRIMARY KEY AUTO_INCREMENT, species_id BIGINT NOT NULL, name VARCHAR(120) NOT NULL, UNIQUE(species_id, name));
CREATE TABLE pets (id BIGINT PRIMARY KEY AUTO_INCREMENT, owner_id BIGINT NOT NULL, name VARCHAR(120) NOT NULL, species_id BIGINT NOT NULL, breed_id BIGINT NULL, gender ENUM('male','female','unknown') DEFAULT 'unknown', date_of_birth DATE NULL, color VARCHAR(80) NULL, weight_kg DECIMAL(8,2) NULL, allergies TEXT NULL, notes TEXT NULL, image_path VARCHAR(255) NULL, created_at TIMESTAMP NULL, updated_at TIMESTAMP NULL, deleted_at TIMESTAMP NULL);
CREATE TABLE appointments (id BIGINT PRIMARY KEY AUTO_INCREMENT, owner_id BIGINT NOT NULL, pet_id BIGINT NOT NULL, doctor_id BIGINT NULL, scheduled_at DATETIME NOT NULL, type ENUM('appointment','walk_in') NOT NULL, status ENUM('booked','checked_in','completed','cancelled') DEFAULT 'booked', reason TEXT NULL, created_at TIMESTAMP NULL, updated_at TIMESTAMP NULL);
CREATE TABLE visits (id BIGINT PRIMARY KEY AUTO_INCREMENT, appointment_id BIGINT NULL, pet_id BIGINT NOT NULL, doctor_id BIGINT NULL, check_in_at DATETIME NOT NULL, status ENUM('in_queue','in_consultation','completed') DEFAULT 'in_queue');
CREATE TABLE consultations (id BIGINT PRIMARY KEY AUTO_INCREMENT, visit_id BIGINT NOT NULL, symptoms TEXT NULL, diagnosis TEXT NULL, treatment_notes TEXT NULL, followup_instructions TEXT NULL, status ENUM('draft','finalized') DEFAULT 'draft', created_by BIGINT NULL, created_at TIMESTAMP NULL, updated_at TIMESTAMP NULL);
CREATE TABLE medicines (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(150) NOT NULL, sku VARCHAR(80) UNIQUE NULL, unit VARCHAR(40) NOT NULL, reorder_level INT DEFAULT 0, is_active TINYINT(1) DEFAULT 1, created_at TIMESTAMP NULL, updated_at TIMESTAMP NULL);
CREATE TABLE medicine_batches (id BIGINT PRIMARY KEY AUTO_INCREMENT, medicine_id BIGINT NOT NULL, batch_no VARCHAR(80) NOT NULL, expiry_date DATE NULL, quantity INT NOT NULL, cost_price DECIMAL(12,2) NOT NULL, selling_price DECIMAL(12,2) NOT NULL, UNIQUE(medicine_id,batch_no));
CREATE TABLE prescriptions (id BIGINT PRIMARY KEY AUTO_INCREMENT, consultation_id BIGINT NOT NULL, notes TEXT NULL, created_at TIMESTAMP NULL, updated_at TIMESTAMP NULL);
CREATE TABLE prescription_items (id BIGINT PRIMARY KEY AUTO_INCREMENT, prescription_id BIGINT NOT NULL, medicine_id BIGINT NOT NULL, dosage VARCHAR(120) NOT NULL, frequency VARCHAR(120) NOT NULL, days INT NOT NULL, quantity INT NOT NULL);
CREATE TABLE pharmacy_issues (id BIGINT PRIMARY KEY AUTO_INCREMENT, prescription_id BIGINT NOT NULL, issued_by BIGINT NULL, status ENUM('issued','cancelled') DEFAULT 'issued', created_at TIMESTAMP NULL, updated_at TIMESTAMP NULL);
CREATE TABLE pharmacy_issue_items (id BIGINT PRIMARY KEY AUTO_INCREMENT, pharmacy_issue_id BIGINT NOT NULL, medicine_batch_id BIGINT NOT NULL, quantity INT NOT NULL, unit_price DECIMAL(12,2) NOT NULL);
CREATE TABLE wards (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(120) NOT NULL, type VARCHAR(60) NULL);
CREATE TABLE beds (id BIGINT PRIMARY KEY AUTO_INCREMENT, ward_id BIGINT NOT NULL, code VARCHAR(50) NOT NULL, status ENUM('available','occupied','maintenance') DEFAULT 'available');
CREATE TABLE admissions (id BIGINT PRIMARY KEY AUTO_INCREMENT, pet_id BIGINT NOT NULL, consultation_id BIGINT NULL, admitted_at DATETIME NOT NULL, bed_id BIGINT NULL, status ENUM('admitted','discharged') DEFAULT 'admitted', notes TEXT NULL, created_at TIMESTAMP NULL, updated_at TIMESTAMP NULL);
CREATE TABLE treatment_records (id BIGINT PRIMARY KEY AUTO_INCREMENT, admission_id BIGINT NOT NULL, recorded_at DATETIME NOT NULL, notes TEXT NOT NULL, created_by BIGINT NULL);
CREATE TABLE discharge_summaries (id BIGINT PRIMARY KEY AUTO_INCREMENT, admission_id BIGINT NOT NULL UNIQUE, summary TEXT NOT NULL, instructions TEXT NULL, follow_up_date DATE NULL, approved_by BIGINT NULL, created_at TIMESTAMP NULL, updated_at TIMESTAMP NULL);
CREATE TABLE invoices (id BIGINT PRIMARY KEY AUTO_INCREMENT, invoice_no VARCHAR(50) UNIQUE NOT NULL, owner_id BIGINT NOT NULL, pet_id BIGINT NOT NULL, status ENUM('draft','issued','partial','paid','cancelled') DEFAULT 'draft', subtotal DECIMAL(14,2) DEFAULT 0, discount DECIMAL(14,2) DEFAULT 0, tax DECIMAL(14,2) DEFAULT 0, total DECIMAL(14,2) DEFAULT 0, balance DECIMAL(14,2) DEFAULT 0, created_at TIMESTAMP NULL, updated_at TIMESTAMP NULL);
CREATE TABLE invoice_items (id BIGINT PRIMARY KEY AUTO_INCREMENT, invoice_id BIGINT NOT NULL, source_type VARCHAR(50) NOT NULL, source_id BIGINT NULL, description VARCHAR(255) NOT NULL, quantity DECIMAL(10,2) NOT NULL, unit_price DECIMAL(14,2) NOT NULL, line_total DECIMAL(14,2) NOT NULL);
CREATE TABLE payments (id BIGINT PRIMARY KEY AUTO_INCREMENT, invoice_id BIGINT NOT NULL, method VARCHAR(60) NOT NULL, amount DECIMAL(14,2) NOT NULL, reference_no VARCHAR(120) NULL, paid_at DATETIME NOT NULL, received_by BIGINT NULL);
CREATE TABLE refunds (id BIGINT PRIMARY KEY AUTO_INCREMENT, payment_id BIGINT NOT NULL, amount DECIMAL(14,2) NOT NULL, reason TEXT NULL, refunded_at DATETIME NOT NULL, processed_by BIGINT NULL);
CREATE TABLE suppliers (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(150) NOT NULL, contact_person VARCHAR(120) NULL, phone VARCHAR(40) NULL, email VARCHAR(190) NULL, address TEXT NULL);
CREATE TABLE purchases (id BIGINT PRIMARY KEY AUTO_INCREMENT, supplier_id BIGINT NOT NULL, po_no VARCHAR(60) UNIQUE NOT NULL, status ENUM('draft','ordered','received','cancelled') DEFAULT 'draft', ordered_at DATETIME NULL, received_at DATETIME NULL, total DECIMAL(14,2) DEFAULT 0);
CREATE TABLE purchase_items (id BIGINT PRIMARY KEY AUTO_INCREMENT, purchase_id BIGINT NOT NULL, medicine_id BIGINT NOT NULL, quantity INT NOT NULL, unit_cost DECIMAL(12,2) NOT NULL, line_total DECIMAL(14,2) NOT NULL);
CREATE TABLE stock_movements (id BIGINT PRIMARY KEY AUTO_INCREMENT, medicine_id BIGINT NOT NULL, batch_id BIGINT NULL, movement_type ENUM('purchase_receive','dispense','adjustment','return') NOT NULL, quantity INT NOT NULL, reference_type VARCHAR(60) NOT NULL, reference_id BIGINT NOT NULL, moved_at DATETIME NOT NULL, created_by BIGINT NULL);
CREATE TABLE chart_of_accounts (id BIGINT PRIMARY KEY AUTO_INCREMENT, code VARCHAR(30) UNIQUE NOT NULL, name VARCHAR(150) NOT NULL, type ENUM('asset','liability','equity','income','expense') NOT NULL);
CREATE TABLE ledger_entries (id BIGINT PRIMARY KEY AUTO_INCREMENT, account_id BIGINT NOT NULL, entry_date DATE NOT NULL, debit DECIMAL(14,2) DEFAULT 0, credit DECIMAL(14,2) DEFAULT 0, memo VARCHAR(255) NULL, reference_type VARCHAR(60) NULL, reference_id BIGINT NULL);
CREATE TABLE expenses (id BIGINT PRIMARY KEY AUTO_INCREMENT, account_id BIGINT NOT NULL, amount DECIMAL(14,2) NOT NULL, expense_date DATE NOT NULL, description VARCHAR(255) NOT NULL);
CREATE TABLE settings (id BIGINT PRIMARY KEY AUTO_INCREMENT, `key` VARCHAR(120) UNIQUE NOT NULL, `value` JSON NULL);
CREATE TABLE audit_logs (id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id BIGINT NULL, action VARCHAR(120) NOT NULL, auditable_type VARCHAR(120) NOT NULL, auditable_id BIGINT NOT NULL, old_values JSON NULL, new_values JSON NULL, ip_address VARCHAR(64) NULL, created_at TIMESTAMP NULL);
